-- AI/ML pathway ("Cipher Division") Act 10 -- "Classical Machine Arena" content.
-- Closes Arc II ("Machines That Predict", Acts 7-12) with a full model
-- tournament: k-NN, Naive Bayes, SVM, hyperparameter search and cross
-- validation, resolved on robustness rather than a single lucky score.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other pathway. The world/act rows
-- already exist (world-ai-classical-machine-arena, act-ai-2).

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-ai-classical-machine-arena', 'world-ai-classical-machine-arena', 'classical-machine-arena', '10A - Classical Machine Arena', 'Every classical model family Cipher Division has not yet tried -- k-NN, Naive Bayes, SVM -- enters a structured tournament, judged by cross-validation rather than a single flattering split, to settle the production emergency classifier once and for all.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-ai-classical-machine-arena-1', 'campaign-ai-classical-machine-arena', 'new-contenders', 'New Contenders', 'Meet the model families that have not entered the ring yet -- k-NN, Naive Bayes, SVM -- and how each one actually decides.', 1),
  ('operation-ai-classical-machine-arena-2', 'campaign-ai-classical-machine-arena', 'the-fair-fight', 'The Fair Fight', 'Search hyperparameters honestly, validate across folds, and let the most robust model win -- not the luckiest one.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-ai-classical-machine-arena-01', 'world-ai-classical-machine-arena', 'campaign-ai-classical-machine-arena', 'operation-ai-classical-machine-arena-1', 'k-nn', 'k-NN', 'No training phase, no formula -- k-Nearest Neighbors just remembers every example and votes with whichever ones look most alike.', 'beginner', ARRAY['maya','byte'], null, null, '{"type":"simulation","simulationId":"knn-voting-sim"}'::jsonb, '{"xp":160,"credits":30}'::jsonb, false, 1),
  ('mission-ai-classical-machine-arena-02', 'world-ai-classical-machine-arena', 'campaign-ai-classical-machine-arena', 'operation-ai-classical-machine-arena-1', 'distance-metrics', 'Distance Metrics', 'k-NN''s entire personality comes from one choice: how "close" gets measured. Change the metric and the neighbors change with it.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classical-machine-arena-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"distance-metric-sim"}'::jsonb, '{"xp":170,"credits":35}'::jsonb, false, 2),
  ('mission-ai-classical-machine-arena-03', 'world-ai-classical-machine-arena', 'campaign-ai-classical-machine-arena', 'operation-ai-classical-machine-arena-1', 'naive-bayes', 'Naive Bayes', 'Naive Bayes assumes every feature is independent -- an assumption that is almost always wrong, and a classifier that almost always still works.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classical-machine-arena-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"naive-bayes-sim"}'::jsonb, '{"xp":170,"credits":35}'::jsonb, false, 3),
  ('mission-ai-classical-machine-arena-04', 'world-ai-classical-machine-arena', 'campaign-ai-classical-machine-arena', 'operation-ai-classical-machine-arena-1', 'svm', 'SVM', 'A Support Vector Machine does not just separate the classes -- it hunts for the boundary with the widest possible cushion on both sides.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classical-machine-arena-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"svm-boundary-sim"}'::jsonb, '{"xp":180,"credits":35}'::jsonb, false, 4),
  ('mission-ai-classical-machine-arena-05', 'world-ai-classical-machine-arena', 'campaign-ai-classical-machine-arena', 'operation-ai-classical-machine-arena-1', 'margins', 'Margins', 'The margin is the gap between the boundary and the nearest points of either class. Wider margins generalize better -- and support vectors are the only points that decide it.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classical-machine-arena-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"margin-width-sim"}'::jsonb, '{"xp":180,"credits":40}'::jsonb, false, 5),
  ('mission-ai-classical-machine-arena-06', 'world-ai-classical-machine-arena', 'campaign-ai-classical-machine-arena', 'operation-ai-classical-machine-arena-1', 'kernel-intuition', 'Kernel Intuition', 'When no straight line can separate two classes, a kernel reshapes the space itself until a straight line finally can.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classical-machine-arena-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"kernel-trick-sim"}'::jsonb, '{"xp":190,"credits":40}'::jsonb, false, 6),
  ('mission-ai-classical-machine-arena-07', 'world-ai-classical-machine-arena', 'campaign-ai-classical-machine-arena', 'operation-ai-classical-machine-arena-2', 'model-selection', 'Model Selection', 'Six model families now sit on the table. Picking one honestly means comparing them on the same footing, not on whichever demo looked best.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classical-machine-arena-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"model-selection-sim"}'::jsonb, '{"xp":190,"credits":40}'::jsonb, false, 7),
  ('mission-ai-classical-machine-arena-08', 'world-ai-classical-machine-arena', 'campaign-ai-classical-machine-arena', 'operation-ai-classical-machine-arena-2', 'hyperparameters', 'Hyperparameters', 'k in k-NN, C and the kernel in SVM, smoothing in Naive Bayes -- none of these are learned from data. A person, or a search, has to set them first.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classical-machine-arena-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"hyperparameter-sim"}'::jsonb, '{"xp":200,"credits":45}'::jsonb, false, 8),
  ('mission-ai-classical-machine-arena-09', 'world-ai-classical-machine-arena', 'campaign-ai-classical-machine-arena', 'operation-ai-classical-machine-arena-2', 'grid-search', 'Grid Search', 'Grid search tries every combination on a fixed grid of hyperparameter values -- exhaustive, honest, and expensive the moment the grid grows.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classical-machine-arena-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"grid-search-sim"}'::jsonb, '{"xp":200,"credits":45}'::jsonb, false, 9),
  ('mission-ai-classical-machine-arena-10', 'world-ai-classical-machine-arena', 'campaign-ai-classical-machine-arena', 'operation-ai-classical-machine-arena-2', 'random-search', 'Random Search', 'Random search samples combinations instead of enumerating them -- often finding a near-best setting for a fraction of the cost of a full grid.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classical-machine-arena-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"random-search-sim"}'::jsonb, '{"xp":210,"credits":45}'::jsonb, false, 10),
  ('mission-ai-classical-machine-arena-11', 'world-ai-classical-machine-arena', 'campaign-ai-classical-machine-arena', 'operation-ai-classical-machine-arena-2', 'cross-validation', 'Cross Validation', 'One train/test split can be a lucky split. k-fold cross-validation runs the experiment k times and reports how the score actually moves.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classical-machine-arena-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"cross-validation-sim"}'::jsonb, '{"xp":210,"credits":50}'::jsonb, false, 11),
  ('mission-ai-classical-machine-arena-12', 'world-ai-classical-machine-arena', 'campaign-ai-classical-machine-arena', 'operation-ai-classical-machine-arena-2', 'the-tournament', 'The Tournament', 'Every classical model family Cipher Division has built this Arc, evaluated on the same folds. The winner is not the highest score -- it is the model that keeps its score.', 'boss', ARRAY['maya','byte'], '{"requiredMissionIds":["mission-ai-classical-machine-arena-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"tournament-boss-sim"}'::jsonb, '{"xp":650,"credits":145,"badgeIds":["the-tournament"],"skillXp":{"classical_ml":55,"ai_ml_fundamentals":20}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-ai-classical-machine-arena-01', 1, 'maya', 'Regression, logistic regression, trees, forests -- Cipher Division has iterated model by model this Arc, and every time we have picked a favorite off one test run. That stops today.'),
  ('mission-ai-classical-machine-arena-01', 2, 'maya', 'I want an actual tournament. Every reasonable classical model family, evaluated on the same footing, with the same cross-validation protocol. No cherry-picking whichever one we happen to like.'),
  ('mission-ai-classical-machine-arena-01', 3, 'byte', 'Which means three contenders have not even entered the ring yet: k-Nearest Neighbors, Naive Bayes, and Support Vector Machines. First up is the strangest one -- k-NN does not really "train" at all.'),
  ('mission-ai-classical-machine-arena-01', 4, 'byte', 'k-NN stores every training example as-is. To classify something new, it finds the k stored examples that look most similar, and lets them vote.'),

  ('mission-ai-classical-machine-arena-02', 1, 'byte', 'k-NN''s entire personality lives in one word: "similar." How that gets measured is the distance metric, and different metrics can hand you different neighbors from the exact same data.'),
  ('mission-ai-classical-machine-arena-02', 2, 'byte', 'Euclidean distance is straight-line distance -- the default, and usually the right start. Manhattan distance sums the differences along each axis, like walking city blocks instead of cutting through buildings.'),

  ('mission-ai-classical-machine-arena-03', 1, 'byte', 'Naive Bayes makes one bold assumption up front: every feature is independent of every other feature, given the class. That is almost never literally true.'),
  ('mission-ai-classical-machine-arena-03', 2, 'byte', 'And yet it works, often shockingly well, because it does not need the assumption to be true -- it just needs the ranking of probabilities it produces to point at the right class most of the time.'),

  ('mission-ai-classical-machine-arena-04', 1, 'byte', 'A Support Vector Machine looks for a decision boundary too, but with a stricter standard: it wants the boundary that leaves the widest possible gap before touching either class.'),
  ('mission-ai-classical-machine-arena-04', 2, 'byte', 'Logistic regression finds a boundary that fits the data well on average. SVM finds the boundary that survives the worst case -- the points closest to the line on both sides.'),

  ('mission-ai-classical-machine-arena-05', 1, 'byte', 'That gap has a name: the margin. It is measured from the boundary to the nearest point of each class, and a wider margin tends to generalize better to new data.'),
  ('mission-ai-classical-machine-arena-05', 2, 'byte', 'Only a handful of points actually pin the margin in place -- the support vectors. Move any other point and the boundary does not budge. Move a support vector and the whole thing shifts.'),

  ('mission-ai-classical-machine-arena-06', 1, 'byte', 'Sometimes no straight line separates two classes, no matter how the margin is drawn. A kernel handles that without ever explicitly transforming the data by hand.'),
  ('mission-ai-classical-machine-arena-06', 2, 'byte', 'It acts as if the points were reshaped into a higher-dimensional space where a straight line finally works -- then the boundary gets mapped back, and it looks curved in the original space.'),

  ('mission-ai-classical-machine-arena-07', 1, 'byte', 'Six model families are now on the table: linear and logistic regression, decision trees, forests, and now k-NN, Naive Bayes, and SVM. Model selection is the discipline of choosing between them honestly.'),
  ('mission-ai-classical-machine-arena-07', 2, 'byte', 'Honestly means the same data, the same split protocol, the same metric, and no one model getting a friendlier evaluation than the others just because it is the one someone is rooting for.'),

  ('mission-ai-classical-machine-arena-08', 1, 'byte', 'Every one of these models has settings nobody learns from data: k in k-NN, C and the kernel choice in SVM, the smoothing constant in Naive Bayes. Those are hyperparameters.'),
  ('mission-ai-classical-machine-arena-08', 2, 'byte', 'Pick them badly and even the right model family loses to a worse one that happened to get tuned properly. They have to be searched for, not guessed once and left alone.'),

  ('mission-ai-classical-machine-arena-09', 1, 'byte', 'Grid search is the exhaustive option: lay out a fixed set of values for each hyperparameter, try every combination, keep whichever combination scored best.'),
  ('mission-ai-classical-machine-arena-09', 2, 'byte', 'It is thorough and it is honest -- and it is also expensive. Add one more hyperparameter with five values and the grid does not grow by five, it multiplies.'),

  ('mission-ai-classical-machine-arena-10', 1, 'byte', 'Random search samples combinations at random from the same ranges instead of enumerating every one. It sounds worse. In practice, it often is not.'),
  ('mission-ai-classical-machine-arena-10', 2, 'byte', 'With many hyperparameters, most of them barely matter for a given model. Random search spends its budget covering more of the space instead of exhaustively grinding through settings that were never going to help.'),

  ('mission-ai-classical-machine-arena-11', 1, 'byte', 'One more problem before the tournament runs: a single train/test split can just be lucky, or unlucky. Score a model on one split and you have one number, not evidence.'),
  ('mission-ai-classical-machine-arena-11', 2, 'byte', 'k-fold cross-validation splits the data into k folds, trains on k-1 of them and tests on the one left out, then rotates through until every fold has been the test set once.'),
  ('mission-ai-classical-machine-arena-11', 3, 'byte', 'That gives k scores instead of one -- a mean, which is nice, and a spread, which is the part everyone is tempted to skip.'),

  ('mission-ai-classical-machine-arena-12', 1, 'maya', 'The tournament ran. Six model families, tuned by search, scored across the same folds. Now Cipher Division has to read the results instead of just admiring the highest number.'),
  ('mission-ai-classical-machine-arena-12', 2, 'byte', 'I have the full cross-validation report queued up, plus what each finalist costs to run and how easy it is to explain to someone who is not us. All three matter for what happens next.'),
  ('mission-ai-classical-machine-arena-12', 3, 'maya', 'Somewhere in that report is a model that posted the single highest score on one fold. That is not the same question as which model deserves to run in production.'),
  ('mission-ai-classical-machine-arena-12', 4, 'maya', 'Judge the evidence, weigh what it actually costs to deploy each finalist, and then choose. Not the lucky model. The one that keeps its score.'),
  ('mission-ai-classical-machine-arena-12', 5, 'maya', 'This tournament was never really about which model wins. It proves Cipher Division can put any model on trial, on this problem or the next one, and trust the verdict.'),
  ('mission-ai-classical-machine-arena-12', 6, 'byte', 'And every model this Arc shared one thing in common: a person handed it the features. k-NN, Naive Bayes, SVM, the trees before them -- none of them found their own representations. We decided what they were even allowed to see.'),
  ('mission-ai-classical-machine-arena-12', 7, 'maya', 'That will not hold forever. Somewhere ahead is a kind of model that learns its own representations straight from raw data, with nobody hand-picking features first. It starts as small as a single artificial neuron.'),
  ('mission-ai-classical-machine-arena-12', 8, 'byte', 'One neuron, deciding what matters on its own. Whatever Echo actually is, I would bet it never waited for anyone to hand it a feature list either.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-ai-classical-machine-arena-01-o1', 'mission-ai-classical-machine-arena-01', 1, 'Understand the vote', 'Identify how k-NN actually decides a classification with no training phase of its own.'),
  ('mission-ai-classical-machine-arena-01-o2', 'mission-ai-classical-machine-arena-01', 2, 'Choose k wisely', 'Reason about what happens to k-NN''s behavior as k changes.'),

  ('mission-ai-classical-machine-arena-02-o1', 'mission-ai-classical-machine-arena-02', 1, 'Match the metric', 'Match each distance metric to how it actually measures closeness.'),
  ('mission-ai-classical-machine-arena-02-o2', 'mission-ai-classical-machine-arena-02', 2, 'Diagnose the mismatch', 'Find the evidence that explains why an unscaled feature is dominating k-NN''s distance calculation.'),

  ('mission-ai-classical-machine-arena-03-o1', 'mission-ai-classical-machine-arena-03', 1, 'Name the assumption', 'Identify the independence assumption Naive Bayes makes and why it is called "naive."'),
  ('mission-ai-classical-machine-arena-03-o2', 'mission-ai-classical-machine-arena-03', 2, 'Explain why it still works', 'Choose the correct explanation for why Naive Bayes performs well despite a false assumption.'),

  ('mission-ai-classical-machine-arena-04-o1', 'mission-ai-classical-machine-arena-04', 1, 'Define the goal', 'Choose the accurate description of what an SVM optimizes for.'),
  ('mission-ai-classical-machine-arena-04-o2', 'mission-ai-classical-machine-arena-04', 2, 'Contrast with logistic regression', 'State the practical difference between SVM''s boundary and logistic regression''s boundary.'),

  ('mission-ai-classical-machine-arena-05-o1', 'mission-ai-classical-machine-arena-05', 1, 'Find the support vectors', 'Identify which points actually determine an SVM''s margin.'),
  ('mission-ai-classical-machine-arena-05-o2', 'mission-ai-classical-machine-arena-05', 2, 'Judge the margin', 'Choose which of two candidate boundaries is more likely to generalize well.'),

  ('mission-ai-classical-machine-arena-06-o1', 'mission-ai-classical-machine-arena-06', 1, 'Spot when a kernel is needed', 'Identify the situation where a linear SVM boundary cannot possibly separate the classes.'),
  ('mission-ai-classical-machine-arena-06-o2', 'mission-ai-classical-machine-arena-06', 2, 'Describe the trick', 'Choose the accurate description of what the kernel trick actually does.'),

  ('mission-ai-classical-machine-arena-07-o1', 'mission-ai-classical-machine-arena-07', 1, 'Match model to strength', 'Match each model family to its core idea and its clearest strength or weakness.'),
  ('mission-ai-classical-machine-arena-07-o2', 'mission-ai-classical-machine-arena-07', 2, 'Spot the unfair comparison', 'Find the evidence showing one model was evaluated less rigorously than the others.'),

  ('mission-ai-classical-machine-arena-08-o1', 'mission-ai-classical-machine-arena-08', 1, 'Tell parameters from hyperparameters', 'Sort each setting into learned parameter or hyperparameter.'),
  ('mission-ai-classical-machine-arena-08-o2', 'mission-ai-classical-machine-arena-08', 2, 'Predict the failure mode', 'Choose what is most likely to happen when a hyperparameter is left at a poor default.'),

  ('mission-ai-classical-machine-arena-09-o1', 'mission-ai-classical-machine-arena-09', 1, 'Define grid search', 'Choose the accurate description of how grid search explores hyperparameters.'),
  ('mission-ai-classical-machine-arena-09-o2', 'mission-ai-classical-machine-arena-09', 2, 'Count the cost', 'Identify the evidence showing why grid search became too expensive to finish.'),

  ('mission-ai-classical-machine-arena-10-o1', 'mission-ai-classical-machine-arena-10', 1, 'Match search to situation', 'Match grid search and random search to the situation where each is the better choice.'),
  ('mission-ai-classical-machine-arena-10-o2', 'mission-ai-classical-machine-arena-10', 2, 'Explain the efficiency', 'Choose the correct reason random search can outperform grid search on a fixed budget.'),

  ('mission-ai-classical-machine-arena-11-o1', 'mission-ai-classical-machine-arena-11', 1, 'Order the fold rotation', 'Put the steps of k-fold cross-validation in the order they actually happen.'),
  ('mission-ai-classical-machine-arena-11-o2', 'mission-ai-classical-machine-arena-11', 2, 'Read the spread', 'Find the evidence that reveals a model is unreliable despite a high average score.'),

  ('mission-ai-classical-machine-arena-12-o1', 'mission-ai-classical-machine-arena-12', 1, 'Resist the lucky fold', 'Judge the cross-validation evidence to find the model that is actually most consistent across folds, not just the one with the single highest score.'),
  ('mission-ai-classical-machine-arena-12-o2', 'mission-ai-classical-machine-arena-12', 2, 'Weigh the tradeoffs', 'Weigh interpretability and inference cost among the finalists to judge which is practical to actually run.'),
  ('mission-ai-classical-machine-arena-12-o3', 'mission-ai-classical-machine-arena-12', 3, 'Choose the champion', 'Choose the model family that is most robust across folds and most defensible against genuinely new, unseen Echo-related incidents.'),
  ('mission-ai-classical-machine-arena-12-o4', 'mission-ai-classical-machine-arena-12', 4, 'Close the tournament', 'Having judged robustness, tradeoffs, and generalization, state what the tournament actually proved Cipher Division now has.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-ai-classical-machine-arena-01-o1-c1', 'mission-ai-classical-machine-arena-01-o1', 1, 'multiple_choice', 'How does k-NN classify a brand new example?', '{"question":"How does k-NN classify a brand new example?","options":[{"id":"a","text":"It fits parameters during a training phase and applies a formula"},{"id":"b","text":"It finds the k stored training examples most similar to it and lets them vote on the class"},{"id":"c","text":"It builds a tree of if/else splits ahead of time"},{"id":"d","text":"It estimates a probability distribution over all features in advance"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-classical-machine-arena-01-o2-c1', 'mission-ai-classical-machine-arena-01-o2', 1, 'multiple_choice', 'What generally happens to k-NN''s decision boundary as k grows very large?', '{"question":"What generally happens to k-NN''s decision boundary as k grows very large?","options":[{"id":"a","text":"It becomes jagged and sensitive to individual noisy points"},{"id":"b","text":"It becomes smoother and more stable, but can miss real local structure"},{"id":"c","text":"It disappears entirely"},{"id":"d","text":"k has no effect on the boundary"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-classical-machine-arena-02-o1-c1', 'mission-ai-classical-machine-arena-02-o1', 1, 'drag_and_drop', 'Match each distance metric to how it measures closeness.', '{"items":[{"id":"i1","text":"Euclidean distance"},{"id":"i2","text":"Manhattan distance"},{"id":"i3","text":"Cosine distance"}],"targets":[{"id":"t1","label":"Straight-line distance through space"},{"id":"t2","label":"Sum of differences along each axis, like city blocks"},{"id":"t3","label":"Angle between two vectors, ignoring their magnitude"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3"}}'::jsonb),
  ('mission-ai-classical-machine-arena-02-o2-c1', 'mission-ai-classical-machine-arena-02-o2', 1, 'investigation', 'A k-NN model trained on incident duration (seconds, 0-100000) and severity score (0-10) is dominated entirely by duration. Why?', '{"evidence":[{"id":"e1","label":"Feature stats","detail":"Incident duration ranges up to 100000; severity score ranges only 0 to 10, and neither feature was scaled before training"},{"id":"e2","label":"Model config","detail":"k was set to 5 for this run"},{"id":"e3","label":"Data log","detail":"The dataset contains roughly 8000 labeled incidents"}],"question":"Why is duration dominating the distance calculation and drowning out severity?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-classical-machine-arena-03-o1-c1', 'mission-ai-classical-machine-arena-03-o1', 1, 'multiple_choice', 'What does Naive Bayes assume that earns it the name "naive"?', '{"question":"What does Naive Bayes assume that earns it the name naive?","options":[{"id":"a","text":"That every feature is independent of every other feature, given the class"},{"id":"b","text":"That the data has no noise at all"},{"id":"c","text":"That there are only two possible classes"},{"id":"d","text":"That every feature is equally important"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-classical-machine-arena-03-o2-c1', 'mission-ai-classical-machine-arena-03-o2', 1, 'multiple_choice', 'Why does Naive Bayes often still classify well despite its independence assumption being false?', '{"question":"Why does Naive Bayes often still classify well despite its independence assumption being false?","options":[{"id":"a","text":"It usually only needs the relative ranking of class probabilities to be right, not the exact probability values"},{"id":"b","text":"Because the assumption is actually true for most real data"},{"id":"c","text":"Because it secretly retrains itself to fix the assumption"},{"id":"d","text":"It does not classify well, it is only used for speed"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-ai-classical-machine-arena-04-o1-c1', 'mission-ai-classical-machine-arena-04-o1', 1, 'multiple_choice', 'What is a Support Vector Machine actually optimizing for when it places its decision boundary?', '{"question":"What is a Support Vector Machine actually optimizing for when it places its decision boundary?","options":[{"id":"a","text":"The boundary that best fits the average of all the data points"},{"id":"b","text":"The boundary that leaves the widest possible margin before touching either class"},{"id":"c","text":"The boundary closest to the origin"},{"id":"d","text":"The boundary that minimizes the number of features used"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-classical-machine-arena-04-o2-c1', 'mission-ai-classical-machine-arena-04-o2', 1, 'multiple_choice', 'How does an SVM''s boundary differ in practice from a logistic regression boundary?', '{"question":"How does an SVM''s boundary differ in practice from a logistic regression boundary?","options":[{"id":"a","text":"SVM is decided by the worst-case nearest points on each side; logistic regression fits the data well on average"},{"id":"b","text":"They are mathematically identical in every case"},{"id":"c","text":"Logistic regression cannot produce a decision boundary at all"},{"id":"d","text":"SVM ignores the labels entirely"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-ai-classical-machine-arena-05-o1-c1', 'mission-ai-classical-machine-arena-05-o1', 1, 'multiple_choice', 'Which points actually determine the position of an SVM''s margin?', '{"question":"Which points actually determine the position of an SVM''s margin?","options":[{"id":"a","text":"Every training point equally"},{"id":"b","text":"Only the support vectors -- the points closest to the boundary on each side"},{"id":"c","text":"Only the single most typical point of each class"},{"id":"d","text":"Points are irrelevant, only feature names matter"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-classical-machine-arena-05-o2-c1', 'mission-ai-classical-machine-arena-05-o2', 1, 'investigation', 'Two candidate SVM boundaries separate the training data perfectly. Which is more likely to generalize well to new data?', '{"evidence":[{"id":"e1","label":"Boundary A","detail":"Separates the training data with a narrow margin, close to points on both sides"},{"id":"e2","label":"Boundary B","detail":"Separates the training data with a wide margin, far from the nearest points on both sides"},{"id":"e3","label":"Training log","detail":"Both boundaries were fit on the exact same training set"}],"question":"Which boundary is more likely to generalize well to new, unseen data?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-classical-machine-arena-06-o1-c1', 'mission-ai-classical-machine-arena-06-o1', 1, 'multiple_choice', 'When is a kernel needed instead of a plain linear SVM boundary?', '{"question":"When is a kernel needed instead of a plain linear SVM boundary?","options":[{"id":"a","text":"When the two classes cannot be separated by any straight line or flat plane in the original feature space"},{"id":"b","text":"Whenever there are more than two features"},{"id":"c","text":"Only when the dataset is very small"},{"id":"d","text":"Kernels are never actually necessary"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-classical-machine-arena-06-o2-c1', 'mission-ai-classical-machine-arena-06-o2', 1, 'multiple_choice', 'What does the kernel trick actually do?', '{"question":"What does the kernel trick actually do?","options":[{"id":"a","text":"It deletes hard-to-classify points from the dataset"},{"id":"b","text":"It behaves as though the data were mapped into a higher-dimensional space where a straight line can separate it, without explicitly computing that mapping"},{"id":"c","text":"It reduces the number of features to exactly two"},{"id":"d","text":"It converts the SVM into a decision tree"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-classical-machine-arena-07-o1-c1', 'mission-ai-classical-machine-arena-07-o1', 1, 'drag_and_drop', 'Match each model family to its clearest strength or weakness.', '{"items":[{"id":"i1","text":"k-NN"},{"id":"i2","text":"Naive Bayes"},{"id":"i3","text":"SVM"},{"id":"i4","text":"Decision tree"}],"targets":[{"id":"t1","label":"No training phase, but slow and distance-sensitive at prediction time"},{"id":"t2","label":"Fast and simple, works well even with limited data despite its false independence assumption"},{"id":"t3","label":"Strong margins and kernels, but less naturally interpretable"},{"id":"t4","label":"Very interpretable individually, but prone to overfitting alone"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),
  ('mission-ai-classical-machine-arena-07-o2-c1', 'mission-ai-classical-machine-arena-07-o2', 1, 'investigation', 'A comparison report shows five models evaluated on an identical held-out test set, and one model evaluated only on the data it was trained on. What is wrong with this comparison?', '{"evidence":[{"id":"e1","label":"Report note","detail":"Model F (k-NN) was scored on the same data it was trained on; the other five were scored on a separate held-out set"},{"id":"e2","label":"Report note","detail":"All six models used the same feature set"},{"id":"e3","label":"Report note","detail":"Model F reported the highest accuracy of all six"}],"question":"Which evidence shows the comparison is not actually fair?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-classical-machine-arena-08-o1-c1', 'mission-ai-classical-machine-arena-08-o1', 1, 'drag_and_drop', 'Sort each setting into learned parameter or hyperparameter.', '{"items":[{"id":"i1","text":"k, the number of neighbors in k-NN"},{"id":"i2","text":"The weight coefficients found by an SVM during training"},{"id":"i3","text":"C, the SVM regularization strength"},{"id":"i4","text":"The split thresholds a decision tree learns at each node"}],"targets":[{"id":"hyper","label":"Hyperparameter (set before training)"},{"id":"param","label":"Learned parameter (set by training)"}]}'::jsonb, '{"correctMapping":{"i1":"hyper","i2":"param","i3":"hyper","i4":"param"}}'::jsonb),
  ('mission-ai-classical-machine-arena-08-o2-c1', 'mission-ai-classical-machine-arena-08-o2', 1, 'multiple_choice', 'What is most likely to happen if k in k-NN is left at a poor default, like k=1, on noisy data?', '{"question":"What is most likely to happen if k in k-NN is left at a poor default, like k=1, on noisy data?","options":[{"id":"a","text":"Nothing, k has no real effect"},{"id":"b","text":"The model becomes highly sensitive to individual noisy points and overfits"},{"id":"c","text":"The model automatically corrects for the bad setting during training"},{"id":"d","text":"The model refuses to run"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-classical-machine-arena-09-o1-c1', 'mission-ai-classical-machine-arena-09-o1', 1, 'multiple_choice', 'How does grid search explore hyperparameters?', '{"question":"How does grid search explore hyperparameters?","options":[{"id":"a","text":"It tries every combination of a fixed set of values for each hyperparameter"},{"id":"b","text":"It samples combinations at random"},{"id":"c","text":"It picks values using intuition alone"},{"id":"d","text":"It only ever tests one hyperparameter at a time, never combinations"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-classical-machine-arena-09-o2-c1', 'mission-ai-classical-machine-arena-09-o2', 1, 'investigation', 'A grid search over 3 hyperparameters, each with 10 candidate values, did not finish overnight. Why?', '{"evidence":[{"id":"e1","label":"Search config","detail":"3 hyperparameters times 10 values each means 10 x 10 x 10 = 1000 combinations, each requiring a full model fit and evaluation"},{"id":"e2","label":"Hardware log","detail":"The search ran on a single machine with no parallelization"},{"id":"e3","label":"Dataset log","detail":"The training set contains 50000 rows"}],"question":"Which evidence best explains why the grid search did not finish?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-classical-machine-arena-10-o1-c1', 'mission-ai-classical-machine-arena-10-o1', 1, 'drag_and_drop', 'Match each search strategy to the situation where it is the better choice.', '{"items":[{"id":"i1","text":"Only 2 hyperparameters, each with just a handful of sensible values"},{"id":"i2","text":"5+ hyperparameters, a tight compute budget, and most of them barely matter"}],"targets":[{"id":"grid","label":"Grid search"},{"id":"random","label":"Random search"}]}'::jsonb, '{"correctMapping":{"i1":"grid","i2":"random"}}'::jsonb),
  ('mission-ai-classical-machine-arena-10-o2-c1', 'mission-ai-classical-machine-arena-10-o2', 1, 'multiple_choice', 'Why can random search outperform grid search on a fixed compute budget?', '{"question":"Why can random search outperform grid search on a fixed compute budget?","options":[{"id":"a","text":"Random search cheats by using extra data"},{"id":"b","text":"When only a few hyperparameters actually matter, random search covers more of the useful range instead of spending budget exhaustively grinding through settings that barely affect the outcome"},{"id":"c","text":"Grid search always tests fewer combinations than random search"},{"id":"d","text":"Random search does not need a validation set"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-classical-machine-arena-11-o1-c1', 'mission-ai-classical-machine-arena-11-o1', 1, 'interactive_diagram', 'Order the steps of k-fold cross-validation.', '{"diagramId":"k-fold-cross-validation","hotspots":[{"id":"split","label":"Split the data into k equal folds","explanation":"The full dataset is divided into k roughly equal-sized partitions up front."},{"id":"holdout","label":"Hold out one fold as the test set","explanation":"One fold is set aside; the model will never train on it this round."},{"id":"train","label":"Train on the remaining k-1 folds","explanation":"The model is fit only on the folds that were not held out."},{"id":"score","label":"Score the model on the held-out fold","explanation":"The trained model is evaluated on the fold it never saw during this round."},{"id":"rotate","label":"Rotate which fold is held out and repeat","explanation":"A different fold becomes the test set, and training/scoring repeats until every fold has been held out exactly once."},{"id":"aggregate","label":"Aggregate the k scores into a mean and a spread","explanation":"The k resulting scores are summarized both by their average and by how much they vary."}],"task":"Order the steps of k-fold cross-validation from first to last."}'::jsonb, '{"correctOrderIds":["split","holdout","train","score","rotate","aggregate"]}'::jsonb),
  ('mission-ai-classical-machine-arena-11-o2-c1', 'mission-ai-classical-machine-arena-11-o2', 1, 'investigation', 'Two models both average 88% accuracy across 5 folds. Which evidence reveals one of them is actually unreliable?', '{"evidence":[{"id":"e1","label":"Model X fold scores","detail":"87%, 88%, 89%, 88%, 88% -- a tight, consistent spread"},{"id":"e2","label":"Model Y fold scores","detail":"99%, 61%, 95%, 92%, 93% -- a wide, erratic spread"},{"id":"e3","label":"Both models","detail":"Both were trained on the same 5 folds using the same features"}],"question":"Which evidence reveals a model that is actually unreliable despite a high average score?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-classical-machine-arena-12-o1-c1', 'mission-ai-classical-machine-arena-12-o1', 1, 'investigation', 'The tournament report lists all six finalists'' cross-validation fold scores. Which evidence identifies the model that is actually most consistent, not just the one with the single highest fold score?', '{"evidence":[{"id":"e1","label":"SVM (RBF kernel) folds","detail":"96%, 74%, 95%, 90%, 93% -- mean 89.6%, one spectacular fold, wide spread"},{"id":"e2","label":"Naive Bayes folds","detail":"83%, 84%, 82%, 84%, 83% -- mean 83.2%, very tight spread"},{"id":"e3","label":"Random forest folds","detail":"91%, 90%, 92%, 91%, 90% -- mean 90.8%, tight spread"},{"id":"e4","label":"Ops note","detail":"The single highest individual fold score across all models was SVM''s 96% on fold 1"}],"question":"Which evidence points to the model that is actually most consistent across folds, not just the one that hit the highest single number?"}'::jsonb, '{"requiredEvidenceIds":["e3"]}'::jsonb),
  ('mission-ai-classical-machine-arena-12-o2-c1', 'mission-ai-classical-machine-arena-12-o2', 1, 'multiple_choice', 'Among the top finalists, which practical factors did Maya insist actually belong in the decision, beyond raw cross-validation score?', '{"question":"Among the top finalists, which practical factors did Maya insist actually belong in the decision, beyond raw cross-validation score?","options":[{"id":"a","text":"Only whichever model looks most impressive in a demo"},{"id":"b","text":"How interpretable the model is, what it costs to run at inference time, and how well it should generalize to genuinely new, unseen incidents"},{"id":"c","text":"Only the total training time, nothing else"},{"id":"d","text":"Whichever model Byte personally prefers"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-classical-machine-arena-12-o3-c1', 'mission-ai-classical-machine-arena-12-o3', 1, 'investigation', 'Weighing consistency, interpretability, and inference cost together, which finalist should Cipher Division choose as the production emergency classifier?', '{"evidence":[{"id":"e1","label":"Random forest summary","detail":"Mean 90.8% with a tight fold spread, moderate interpretability via feature importance, moderate inference cost"},{"id":"e2","label":"SVM (RBF kernel) summary","detail":"Mean 89.6% with a wide fold spread including one weak fold, low interpretability, higher inference cost at scale"},{"id":"e3","label":"k-NN summary","detail":"Mean 85.1% with a moderate fold spread, low interpretability, high inference cost since every prediction compares against the full stored dataset"}],"question":"Which finalist is the most defensible choice as the production emergency classifier?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-classical-machine-arena-12-o4-c1', 'mission-ai-classical-machine-arena-12-o4', 1, 'boss_encounter', 'Having judged robustness, tradeoffs, and generalization, state what the tournament actually proved Cipher Division now has.', '{"stages":[{"objectiveRef":"mission-ai-classical-machine-arena-12-o1","label":"Resist the lucky fold"},{"objectiveRef":"mission-ai-classical-machine-arena-12-o2","label":"Weigh the tradeoffs"},{"objectiveRef":"mission-ai-classical-machine-arena-12-o3","label":"Choose the champion"}],"task":"State in one sentence what this tournament actually proved: not which single model wins, but that Cipher Division now has a repeatable, defensible way to choose any model going forward."}'::jsonb, '{"requiredObjectiveIds":["mission-ai-classical-machine-arena-12-o1","mission-ai-classical-machine-arena-12-o2","mission-ai-classical-machine-arena-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-ai-classical-machine-arena-01-o1-c1', 'orientation', 'Think about what happens the moment a new example needs to be classified, not what happens ahead of time.', 10, 1),
  ('mission-ai-classical-machine-arena-01-o1-c1', 'solution', 'k-NN has no real training phase -- it stores the data and, at prediction time, lets the k most similar stored examples vote.', 20, 2),
  ('mission-ai-classical-machine-arena-01-o2-c1', 'orientation', 'A very large k means the vote is coming from a very large neighborhood.', 10, 1),
  ('mission-ai-classical-machine-arena-01-o2-c1', 'solution', 'Large k smooths the boundary and reduces sensitivity to noise, but it can wash out real local structure in the data.', 20, 2),

  ('mission-ai-classical-machine-arena-02-o1-c1', 'orientation', 'Picture walking through a city grid versus flying directly over the rooftops.', 10, 1),
  ('mission-ai-classical-machine-arena-02-o1-c1', 'solution', 'Euclidean is straight-line distance, Manhattan sums axis-by-axis differences, cosine measures the angle between vectors, ignoring their length.', 20, 2),
  ('mission-ai-classical-machine-arena-02-o2-c1', 'orientation', 'Distance metrics do not know that one feature''s numbers are naturally much bigger than another''s.', 10, 1),
  ('mission-ai-classical-machine-arena-02-o2-c1', 'concept', 'A duration difference of 500 seconds dwarfs a severity difference of 3 points numerically, even if severity matters more.', 20, 2),
  ('mission-ai-classical-machine-arena-02-o2-c1', 'solution', 'e1: neither feature was scaled, so duration''s much larger numeric range completely dominates the distance calculation over severity.', 30, 3),

  ('mission-ai-classical-machine-arena-03-o1-c1', 'orientation', 'The name describes an assumption about how features relate to each other, not about the data quality.', 10, 1),
  ('mission-ai-classical-machine-arena-03-o1-c1', 'solution', 'Naive Bayes assumes every feature is independent of every other feature, given the class -- rarely true, which is why it is called naive.', 20, 2),
  ('mission-ai-classical-machine-arena-03-o2-c1', 'orientation', 'Getting the exact probability right and getting the winning class right are two different bars to clear.', 10, 1),
  ('mission-ai-classical-machine-arena-03-o2-c1', 'solution', 'It usually only needs the relative ranking between classes to be correct, not the precise probability values -- so the false assumption often does not change which class wins.', 20, 2),

  ('mission-ai-classical-machine-arena-04-o1-c1', 'orientation', 'Think about what a "cushion" between the classes would mean geometrically.', 10, 1),
  ('mission-ai-classical-machine-arena-04-o1-c1', 'solution', 'An SVM optimizes for the boundary that leaves the widest possible margin before touching either class.', 20, 2),
  ('mission-ai-classical-machine-arena-04-o2-c1', 'orientation', 'One method cares about every point on average, the other cares most about the hardest, closest points.', 10, 1),
  ('mission-ai-classical-machine-arena-04-o2-c1', 'solution', 'SVM is shaped by the worst-case nearest points on each side; logistic regression fits the overall data well on average.', 20, 2),

  ('mission-ai-classical-machine-arena-05-o1-c1', 'orientation', 'Most training points could move slightly without changing the boundary at all. A few could not.', 10, 1),
  ('mission-ai-classical-machine-arena-05-o1-c1', 'solution', 'Only the support vectors -- the points nearest the boundary on each side -- actually determine the margin.', 20, 2),
  ('mission-ai-classical-machine-arena-05-o2-c1', 'orientation', 'A narrow margin leaves almost no room before a new, slightly different point crosses to the wrong side.', 10, 1),
  ('mission-ai-classical-machine-arena-05-o2-c1', 'solution', 'e2: the wide-margin boundary has more cushion against new data landing just slightly differently than the training data did.', 20, 2),

  ('mission-ai-classical-machine-arena-06-o1-c1', 'orientation', 'Ask whether a single straight line or flat plane could ever divide the two classes cleanly.', 10, 1),
  ('mission-ai-classical-machine-arena-06-o1-c1', 'solution', 'A kernel becomes necessary when the classes are not linearly separable in the original feature space -- no straight boundary works there.', 20, 2),
  ('mission-ai-classical-machine-arena-06-o2-c1', 'orientation', 'The trick avoids ever actually computing the higher-dimensional coordinates directly.', 10, 1),
  ('mission-ai-classical-machine-arena-06-o2-c1', 'solution', 'The kernel trick behaves as if the data were mapped to a higher-dimensional space where a line separates it, without ever explicitly computing that mapping.', 20, 2),

  ('mission-ai-classical-machine-arena-07-o1-c1', 'orientation', 'Match each model to the thing you already learned makes it distinctive this Act.', 10, 1),
  ('mission-ai-classical-machine-arena-07-o1-c1', 'solution', 'k-NN: no training, slow at prediction time. Naive Bayes: fast and simple despite a false assumption. SVM: strong margins, less interpretable. Decision tree: interpretable alone, prone to overfitting.', 20, 2),
  ('mission-ai-classical-machine-arena-07-o2-c1', 'orientation', 'A fair comparison means every model is scored the same way, on data none of them trained on.', 10, 1),
  ('mission-ai-classical-machine-arena-07-o2-c1', 'solution', 'e1: Model F was scored on its own training data while the others were scored on a held-out set -- its score is not comparable to theirs.', 20, 2),

  ('mission-ai-classical-machine-arena-08-o1-c1', 'orientation', 'Ask whether the value gets set before training starts, or discovered by training itself.', 10, 1),
  ('mission-ai-classical-machine-arena-08-o1-c1', 'solution', 'Hyperparameters: k, and C. Learned parameters: SVM''s weight coefficients, and a tree''s learned split thresholds.', 20, 2),
  ('mission-ai-classical-machine-arena-08-o2-c1', 'orientation', 'k=1 means every prediction depends entirely on the single closest stored point.', 10, 1),
  ('mission-ai-classical-machine-arena-08-o2-c1', 'solution', 'With k=1 on noisy data, a single mislabeled or unusual neighbor can flip a prediction -- the model overfits to noise.', 20, 2),

  ('mission-ai-classical-machine-arena-09-o1-c1', 'orientation', 'Think "every combination," not "some combinations."', 10, 1),
  ('mission-ai-classical-machine-arena-09-o1-c1', 'solution', 'Grid search tries every combination of a fixed set of candidate values across all hyperparameters being tuned.', 20, 2),
  ('mission-ai-classical-machine-arena-09-o2-c1', 'orientation', 'Multiply the number of values per hyperparameter together, not add them.', 10, 1),
  ('mission-ai-classical-machine-arena-09-o2-c1', 'solution', 'e1: 3 hyperparameters with 10 values each is 1000 combinations, each needing a full fit and evaluation -- that is what exhausted the overnight budget.', 20, 2),

  ('mission-ai-classical-machine-arena-10-o1-c1', 'orientation', 'A small, well-understood space favors being exhaustive. A large, mostly-irrelevant space favors sampling.', 10, 1),
  ('mission-ai-classical-machine-arena-10-o1-c1', 'solution', 'Grid search fits a small space with few sensible values. Random search fits a large space with a tight budget where most hyperparameters barely matter.', 20, 2),
  ('mission-ai-classical-machine-arena-10-o2-c1', 'orientation', 'Ask where an exhaustive grid actually wastes its evaluations.', 10, 1),
  ('mission-ai-classical-machine-arena-10-o2-c1', 'solution', 'When few hyperparameters truly matter, random search spreads its budget across more of the useful range instead of grinding through combinations of settings that barely move the outcome.', 20, 2),

  ('mission-ai-classical-machine-arena-11-o1-c1', 'orientation', 'Nothing can be scored on a held-out fold until the model has actually been trained on the rest.', 10, 1),
  ('mission-ai-classical-machine-arena-11-o1-c1', 'concept', 'The whole point is that every fold gets a turn being the held-out test set, not just one.', 20, 2),
  ('mission-ai-classical-machine-arena-11-o1-c1', 'solution', 'Split into k folds, hold out one, train on the rest, score on the held-out fold, rotate and repeat, then aggregate the k scores into a mean and a spread.', 30, 3),
  ('mission-ai-classical-machine-arena-11-o2-c1', 'orientation', 'A high average can hide wild swings underneath it. Look at the individual fold numbers, not just the mean.', 10, 1),
  ('mission-ai-classical-machine-arena-11-o2-c1', 'solution', 'e2: Model Y''s fold scores swing from 61% to 99% -- the same 88% average as a much more stable model, but far less trustworthy.', 20, 2),

  ('mission-ai-classical-machine-arena-12-o1-c1', 'orientation', 'The highest single fold score and the most consistent model are not necessarily the same model.', 10, 1),
  ('mission-ai-classical-machine-arena-12-o1-c1', 'concept', 'A model that swings from a spectacular fold to a weak one is not actually more trustworthy than one that stays tight around its mean.', 20, 2),
  ('mission-ai-classical-machine-arena-12-o1-c1', 'solution', 'e3: random forest posts the highest mean with the tightest spread across folds -- more consistent than SVM''s higher-variance run, despite SVM hitting the single best fold.', 30, 3),
  ('mission-ai-classical-machine-arena-12-o2-c1', 'orientation', 'Maya has been pushing for evidence over gut feeling all Act -- her practical checklist is broader than accuracy alone.', 10, 1),
  ('mission-ai-classical-machine-arena-12-o2-c1', 'solution', 'Interpretability, inference cost, and how well a model should generalize to genuinely new, unseen incidents all belong in the decision alongside cross-validation score.', 20, 2),
  ('mission-ai-classical-machine-arena-12-o3-c1', 'orientation', 'Weigh consistency, explainability, and running cost together -- no single number wins alone.', 10, 1),
  ('mission-ai-classical-machine-arena-12-o3-c1', 'solution', 'e1: random forest combines a strong, consistent cross-validation score with reasonable interpretability and moderate inference cost -- the most defensible production choice.', 20, 2),
  ('mission-ai-classical-machine-arena-12-o4-c1', 'orientation', 'Look at what the whole exercise demonstrated as a method, not just which model happened to come out ahead.', 15, 1),
  ('mission-ai-classical-machine-arena-12-o4-c1', 'solution', 'The tournament proved Cipher Division now has a repeatable, defensible process for choosing between any models -- robustness over a lucky score -- not just one winning answer for today.', 25, 2);
